-- FF-089: Utah elk hunt unit boundaries — seed hunt_unit_registry for point-in-polygon lookup.
-- Source: Utah DWR ArcGIS (dwrdata), Fall 2026 layers, fetched 2026-09-26 with
-- geometryPrecision=4, maxAllowableOffset=0.001 (simplified, WGS84):
--   general_bull  (29) 2026ElkBullGeneralSeasonAnyBull2
--   limited_entry (28) 2026ElkBullLimitedEntry2
--   spike_only    (24) 2026ElkBullGeneralSeasonSpikeOnly1
-- unit_id = slug of boundary_name (lowercase, commas removed, spaces → hyphens).
-- Centroid = vertex average of the outer ring of the largest polygon.
-- Units overlap across hunt types, so hunt_type joins the unique key.

ALTER TABLE hunt_unit_registry
  ADD COLUMN IF NOT EXISTS hunt_type TEXT,
  ADD COLUMN IF NOT EXISTS boundary_geojson JSONB;

-- Table is empty in production; guard pre-existing rows anyway before NOT NULL
UPDATE hunt_unit_registry SET hunt_type = 'unspecified' WHERE hunt_type IS NULL;
ALTER TABLE hunt_unit_registry ALTER COLUMN hunt_type SET NOT NULL;

-- Drop the original UNIQUE (state, unit_id, species), whatever it was named
DO $$
DECLARE c TEXT;
BEGIN
  SELECT con.conname INTO c
  FROM pg_constraint con
  WHERE con.conrelid = 'hunt_unit_registry'::regclass
    AND con.contype = 'u'
    AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
         FROM pg_attribute a
         WHERE a.attrelid = con.conrelid AND a.attnum = ANY (con.conkey))
        = ARRAY['species', 'state', 'unit_id'];
  IF c IS NOT NULL THEN
    EXECUTE format('ALTER TABLE hunt_unit_registry DROP CONSTRAINT %I', c);
  END IF;
END $$;
ALTER TABLE hunt_unit_registry DROP CONSTRAINT IF EXISTS hunt_unit_registry_state_unit_id_species_hunt_type_key;
ALTER TABLE hunt_unit_registry
  ADD CONSTRAINT hunt_unit_registry_state_unit_id_species_hunt_type_key UNIQUE (state, unit_id, species, hunt_type);

INSERT INTO hunt_unit_registry (state, species, hunt_type, unit_id, unit_name, centroid_lat, centroid_lon, boundary_geojson)
